SRC_FILES = {'src/__init__.py': '', 'src/data/__init__.py': '', 'src/data/load_data.py': '"""Load data DSCO 2025 (deteksi URL phishing)."""\nfrom __future__ import annotations\n\nimport os\nfrom pathlib import Path\n\nimport pandas as pd\n\nTARGET = "ClassLabel"      # 1 = legitimate, 0 = phishing\nID = "ID"\nPROVIDED = ["url_length", "has_ip_address", "dot_count", "https_flag", "url_entropy", "token_count", "subdomain_count",\n            "query_param_count", "tld_length", "path_length", "has_hyphen_in_domain", "number_of_digits", "tld_popularity",\n            "suspicious_file_extension", "domain_name_length", "percentage_numeric_chars"]\n\n\ndef find_data_dir(local: str | Path = "../data/raw") -> Path:\n    """Folder yang berisi train.csv kompetisi ini (di /kaggle/input, ikuti symlink)."""\n    for root, _, files in os.walk("/kaggle/input", followlinks=True):\n        if {"train.csv", "test.csv", "sample_submission.csv"} <= set(files):\n            if "URL" in pd.read_csv(Path(root) / "train.csv", nrows=1).columns:\n                return Path(root)\n    return Path(local)\n\n\ndef load(data_dir: str | Path) -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame]:\n    d = Path(data_dir)\n    train = pd.read_csv(d / "train.csv")\n    train[TARGET] = train[TARGET].astype(int)\n    return train, pd.read_csv(d / "test.csv"), pd.read_csv(d / "sample_submission.csv")\n', 'src/features/__init__.py': '', 'src/features/url_features.py': '"""Fitur yang dihitung ulang langsung dari string URL, penanda ketidakcocokan dengan fitur bawaan, dan tipe URL."""\nfrom __future__ import annotations\n\nimport math\nimport re\nfrom collections import Counter\nfrom urllib.parse import urlparse\n\nimport numpy as np\nimport pandas as pd\n\nRISKY_EXT = r"\\.(exe|zip|rar|sh|apk|bin|dll|jar|scr|war|m|a|i|arm\\d*|mips|x86)$"\n\n\ndef entropy(s: str) -> float:\n    c = Counter(s)\n    n = len(s)\n    return -sum(v / n * math.log2(v / n) for v in c.values())\n\n\ndef _host(u: str) -> str:\n    try:\n        return urlparse(u if "://" in u else "http://" + u).hostname or ""\n    except ValueError:\n        return ""\n\n\ndef url_type(urls: pd.Series) -> pd.Series:\n    """Tiga tipe URL: host berupa alamat IP, beranda polos https://www.<domain>, dan lainnya."""\n    host = urls.map(_host)\n    ip = host.str.fullmatch(r"[\\d.]+").fillna(False)\n    home = urls.str.fullmatch(r"https://www\\.[^/?#]+/?").fillna(False)\n    return pd.Series(np.select([ip, home], ["host IP", "beranda https://www"], "lainnya"), index=urls.index)\n\n\ndef recompute(urls: pd.Series) -> pd.DataFrame:\n    rows = []\n    for u in urls:\n        p = urlparse(u if "://" in u else "http://" + u)\n        try:\n            port = p.port is not None\n        except ValueError:\n            port = False\n        host = p.hostname or ""\n        parts = [x for x in host.split(".") if x]\n        rows.append({\n            "u_len": len(u), "u_https": int(u.startswith("https://")), "u_www": int(host.startswith("www.")),\n            "u_ip": int(bool(re.fullmatch(r"[\\d.]+", host))), "u_port": int(port), "u_host_len": len(host),\n            "u_n_labels": len(parts), "u_tld_len": len(parts[-1]) if parts else 0, "u_hyphen": host.count("-"),\n            "u_path_len": len(p.path), "u_path_depth": p.path.count("/"), "u_query_len": len(p.query),\n            "u_n_params": len([q for q in p.query.split("&") if q]), "u_digits": sum(ch.isdigit() for ch in u),\n            "u_upper": sum(ch.isupper() for ch in u), "u_special": sum(not ch.isalnum() for ch in u),\n            "u_entropy": entropy(u), "u_risky_ext": int(bool(re.search(RISKY_EXT, p.path, re.I))),\n            "u_tokens": len([t for t in re.split(r"[/.?=&\\-_:]+", u) if t]),\n        })\n    out = pd.DataFrame(rows, index=urls.index)\n    out["u_pct_digits"] = out.u_digits / out.u_len * 100\n    return out\n\n\ndef mismatch(provided: pd.DataFrame, clean: pd.DataFrame) -> pd.DataFrame:\n    """1 jika fitur bawaan tidak sama dengan nilai yang dihitung ulang dari URL."""\n    return pd.DataFrame({\n        "beda_entropy": ~np.isclose(provided.url_entropy, clean.u_entropy, atol=1e-3),\n        "beda_path_length": ~np.isclose(provided.path_length, clean.u_path_len, atol=1e-2),\n        "beda_persen_digit": ~np.isclose(provided.percentage_numeric_chars, clean.u_pct_digits, atol=1e-2),\n        "token_count_pecahan": provided.token_count != provided.token_count.round(),\n    }, index=provided.index).astype(int)\n', 'src/models/__init__.py': '', 'src/models/train_model.py': '"""Cross-validation berulang untuk LightGBM, regresi logistik, dan model teks TF-IDF pada string URL."""\nfrom __future__ import annotations\n\nimport lightgbm as lgb\nimport numpy as np\nimport pandas as pd\nfrom sklearn.feature_extraction.text import TfidfVectorizer\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import roc_auc_score\nfrom sklearn.model_selection import StratifiedKFold\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\n\nLGB_PARAMS = dict(n_estimators=600, learning_rate=0.03, num_leaves=31, min_child_samples=20, subsample=0.8,\n                  subsample_freq=1, colsample_bytree=0.8)\n\n\ndef lgb_model(seed: int = 0, **kw):\n    return lgb.LGBMClassifier(**{**LGB_PARAMS, **kw}, random_state=seed, verbose=-1)\n\n\ndef logreg_model(seed: int = 0):\n    return make_pipeline(StandardScaler(), LogisticRegression(C=1.0, max_iter=3000))\n\n\ndef tfidf_model(seed: int = 0):\n    return make_pipeline(TfidfVectorizer(analyzer="char_wb", ngram_range=(2, 5), min_df=3, sublinear_tf=True,\n                                         max_features=300_000),\n                         LogisticRegression(C=5.0, max_iter=3000))\n\n\ndef cv_predict(make_model, X, y, seeds=range(3), n_splits: int = 5) -> np.ndarray:\n    """Probabilitas out-of-fold untuk tiap seed. Hasil: array (n_seed, n_baris)."""\n    y = np.asarray(y)\n    out = np.zeros((len(list(seeds)), len(y)))\n    for i, s in enumerate(seeds):\n        for trn, val in StratifiedKFold(n_splits, shuffle=True, random_state=s).split(np.zeros(len(y)), y):\n            Xt = X.iloc[trn] if hasattr(X, "iloc") else X[trn]\n            Xv = X.iloc[val] if hasattr(X, "iloc") else X[val]\n            out[i, val] = make_model(s).fit(Xt, y[trn]).predict_proba(Xv)[:, 1]\n    return out\n\n\ndef auc_by_seed(oof: np.ndarray, y) -> list[float]:\n    return [roc_auc_score(y, p) for p in np.atleast_2d(oof)]\n\n\ndef rank_mean(*preds) -> np.ndarray:\n    return np.mean([pd.Series(p).rank(pct=True).values for p in preds], axis=0)\n', 'src/visualization/__init__.py': '', 'src/visualization/plots.py': '"""Gaya grafik yang konsisten dan ramah buta warna (palet Okabe–Ito)."""\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nimport matplotlib.pyplot as plt\nimport matplotlib.ticker as mtick\nimport seaborn as sns\n\nPALETTE = {"normal": "#0072B2", "fraud": "#D55E00", "accent": "#009E73", "neutral": "#8C8C8C"}\n\n\ndef set_style() -> None:\n    sns.set_theme(style="whitegrid", context="notebook", palette="colorblind")\n    plt.rcParams.update({"figure.dpi": 110, "axes.titleweight": "bold", "axes.titlesize": 12})\n\n\ndef save_fig(fig_dir: Path, name: str) -> None:\n    """Rapikan layout, simpan PNG ke `fig_dir`, lalu tampilkan."""\n    plt.tight_layout()\n    plt.savefig(Path(fig_dir) / f"{name}.png", dpi=130, bbox_inches="tight")\n    plt.show()\n\n\ndef pct_axis(ax, decimals: int = 1, axis: str = "y") -> None:\n    fmt = mtick.PercentFormatter(1, decimals=decimals)\n    (ax.yaxis if axis == "y" else ax.xaxis).set_major_formatter(fmt)\n\n\ndef ref_line(ax, value: float, label: str = "rata-rata") -> None:\n    ax.axhline(value, color=PALETTE["neutral"], ls="--", lw=1.2, label=label)\n'}
NOTEBOOK = json.loads('{\n "cells": [\n  {\n   "cell_type": "markdown",\n   "id": "59b4aaf2",\n   "metadata": {},\n   "source": [\n    "# Mendeteksi URL Phishing: Apa yang Sebenarnya Dipelajari Model?\\n",\n    "\\n",\n    "| | |\\n",\n    "| --- | --- |\\n",\n    "| **Kompetisi** | [Data Science Olympiads (DSCO) 2025](https://www.kaggle.com/competitions/dsco) (Data Science Club, Kaggle, November–Desember 2025) |\\n",\n    "| **Tujuan** | Membedakan URL *legitimate* (1) dan *phishing* (0) dari string URL dan 16 fitur leksikal (metrik ROC AUC) |\\n",\n    "| **Data** | 80.974 URL berlabel dan 20.244 URL uji, turunan dataset LegitPhish |\\n",\n    "| **Penulis** | Fauzan Ahsanudin Alfikri · [Kaggle: fauzan2](https://www.kaggle.com/fauzan2) |\\n",\n    "| **Tanggal** | Disusun ulang November 2026, menggantikan notebook kompetisi Desember 2025 |\\n",\n    "| **Lingkungan** | Dijalankan penuh di Kaggle (CPU) |\\n",\n    "\\n",\n    "**Pertanyaan penelitian.** Skor AUC di atas 0,99 mudah dicapai di kompetisi ini. Apakah itu berarti model memahami\\n",\n    "phishing, atau hanya mengenali cara dataset ini disusun?\\n",\n    "\\n",\n    "**Ringkasan temuan.**\\n",\n    "- Dataset ini didominasi dua tipe URL: **host berupa alamat IP** (48,5%, hanya 3,3% legitimate) dan **beranda polos `https://www.<domain>`** (36,5%, 96,6% legitimate). Aturan satu baris \\"beranda = legitimate\\" sudah mencapai AUC 0,959.\\n",\n    "- Sekitar 56% baris punya minimal satu fitur bawaan yang tidak cocok dengan string URL-nya (entropi, panjang path, persen digit, jumlah token). Nilai yang diubah ini justru membawa informasi tambahan: di dalam URL host IP, entropi bawaan memisahkan label dengan AUC 0,90, sedangkan entropi yang dihitung ulang dari URL hanya 0,83.\\n",\n    "- LightGBM pada fitur bawaan plus 20 fitur yang dihitung ulang dari URL mencapai **AUC OOF 0,9933**. Model yang hanya memakai fitur bersih dari URL mencapai 0,9876.\\n",\n    "- **92% kesalahan model** berasal dari dua kelompok kecil: host IP berlabel legitimate (1.299 URL, contoh `http://59.89.186.229:59571/bin.sh`) dan beranda berlabel phishing (1.017 URL). Label ini berlawanan dengan isi URL-nya dan kemungkinan besar keliru.\\n",\n    "- Late submission: public **0,99399**, private **0,99390**, di atas submission tim terbaik saat kompetisi (private 0,99378, peringkat akhir 24 dari 90) dan 0,0002 di bawah peringkat 1 (0,99410).\\n",\n    "\\n",\n    "**Alur:** 1. Setup → 2. Memahami data → 3. EDA → 4. Preprocessing → 5. Baseline → 6. Model →\\n",\n    "7. Interpretasi dan analisis error → 8. Submission → 9. Kesimpulan"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "f2884124",\n   "metadata": {},\n   "source": [\n    "## 1. Setup\\n",\n    "\\n",\n    "Semua import, parameter, dan path ada di sel ini. Fitur yang dihitung ulang dari URL ada di `src/features`, dan\\n",\n    "cross-validation ada di `src/models`."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "4a89c707",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "import os\\n",\n    "import shutil\\n",\n    "import sys\\n",\n    "import time\\n",\n    "import warnings\\n",\n    "from importlib.metadata import version\\n",\n    "from pathlib import Path\\n",\n    "\\n",\n    "import numpy as np\\n",\n    "import pandas as pd\\n",\n    "import matplotlib.pyplot as plt\\n",\n    "import seaborn as sns\\n",\n    "from sklearn.metrics import roc_auc_score, roc_curve\\n",\n    "from sklearn.model_selection import StratifiedKFold, cross_val_predict\\n",\n    "\\n",\n    "SRC_ROOT = Path.cwd().parent\\n",\n    "for r, _, f in os.walk(\\"/kaggle/input\\", followlinks=True):\\n",\n    "    if Path(r).name == \\"features\\" and \\"url_features.py\\" in f:\\n",\n    "        pkg = Path(r).parent\\n",\n    "        if pkg.name == \\"src\\":\\n",\n    "            SRC_ROOT = pkg.parent\\n",\n    "        else:\\n",\n    "            SRC_ROOT = Path(\\"/tmp/project\\")\\n",\n    "            shutil.copytree(pkg, SRC_ROOT / \\"src\\", dirs_exist_ok=True)\\n",\n    "        break\\n",\n    "sys.path.insert(0, str(SRC_ROOT))\\n",\n    "from src.data.load_data import ID, PROVIDED, TARGET, find_data_dir, load\\n",\n    "from src.features.url_features import mismatch, recompute, url_type\\n",\n    "from src.models.train_model import auc_by_seed, cv_predict, lgb_model, logreg_model, rank_mean, tfidf_model\\n",\n    "from src.visualization.plots import PALETTE, pct_axis, save_fig, set_style\\n",\n    "\\n",\n    "# ── Parameter eksperimen\\n",\n    "SEEDS = range(3)                 # Stratified 5-Fold diulang dengan 3 seed\\n",\n    "\\n",\n    "# ── Path\\n",\n    "DATA_DIR = find_data_dir(local=\\"../data/raw\\")\\n",\n    "OUT_DIR = Path(\\"/kaggle/working\\") if Path(\\"/kaggle/working\\").exists() else Path(\\"../reports\\")\\n",\n    "FIG_DIR = OUT_DIR / \\"figures\\"\\n",\n    "FIG_DIR.mkdir(parents=True, exist_ok=True)\\n",\n    "\\n",\n    "warnings.filterwarnings(\\"ignore\\")\\n",\n    "set_style()\\n",\n    "C1, C2, C3, CN = PALETTE[\\"normal\\"], PALETTE[\\"fraud\\"], PALETTE[\\"accent\\"], PALETTE[\\"neutral\\"]\\n",\n    "T0 = time.time()\\n",\n    "print(\\"DATA_DIR:\\", DATA_DIR, \\"| OUT_DIR:\\", OUT_DIR)"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "54e6cd3b",\n   "metadata": {},\n   "source": [\n    "## 2. Memahami data\\n",\n    "\\n",\n    "Setiap baris adalah satu URL beserta 16 fitur leksikal yang sudah dihitung penyelenggara: panjang URL, jumlah titik,\\n",\n    "entropi, jumlah token, panjang path, jumlah digit, dan seterusnya. Label `ClassLabel` bernilai 1 untuk URL legitimate dan\\n",\n    "0 untuk phishing."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "52f1ff60",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "train, test, sample = load(DATA_DIR)\\n",\n    "y = train[TARGET].values\\n",\n    "print(f\\"Train: {train.shape} | Test: {test.shape} | nilai kosong train/test: {train.isna().sum().sum()}/{test.isna().sum().sum()}\\")\\n",\n    "print(f\\"Legitimate: {y.mean():.1%} | URL duplikat di train: {train.URL.duplicated().sum()} | URL test yang juga ada di train: {test.URL.isin(train.URL).mean():.2%}\\")\\n",\n    "pd.concat([train[train[TARGET] == k].sample(5, random_state=1)[[\\"URL\\", TARGET]] for k in [1, 0]], ignore_index=True)"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "8f9b178d",\n   "metadata": {},\n   "source": [\n    "**Temuan.** 80.974 URL berlabel tanpa nilai kosong, 37,6% legitimate. Contoh di atas sudah memperlihatkan pola utamanya: URL legitimate hampir semuanya beranda situs dengan `https://www.`, sedangkan URL phishing banyak berupa alamat IP dengan port dan file seperti `/i`, `/bin.sh`, atau `.arm5`. Hanya 0,58% URL test yang juga muncul di train, jadi menghafal URL tidak membantu."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "e068fe39",\n   "metadata": {},\n   "source": [\n    "## 3. Exploratory Data Analysis\\n",\n    "\\n",\n    "### 3.1 Dua tipe URL mendominasi dataset"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "9427fa7d",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "TYPE_TR, TYPE_TE = url_type(train.URL), url_type(test.URL)\\n",\n    "ORDER = [\\"host IP\\", \\"beranda https://www\\", \\"lainnya\\"]\\n",\n    "tt = pd.DataFrame({\\"porsi train\\": TYPE_TR.value_counts(normalize=True), \\"porsi test\\": TYPE_TE.value_counts(normalize=True),\\n",\n    "                   \\"proporsi legit\\": train.groupby(TYPE_TR)[TARGET].mean(), \\"jumlah\\": TYPE_TR.value_counts()}).loc[ORDER]\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(14, 4))\\n",\n    "ax[0].barh(ORDER[::-1], tt[\\"porsi train\\"][::-1], color=C1)\\n",\n    "pct_axis(ax[0], 0, axis=\\"x\\"); ax[0].set(xlabel=\\"porsi URL di train\\", title=\\"Tipe URL\\")\\n",\n    "ax[1].barh(ORDER[::-1], tt[\\"proporsi legit\\"][::-1], color=[C3, C1, C2])\\n",\n    "pct_axis(ax[1], 0, axis=\\"x\\"); ax[1].set(xlabel=\\"proporsi legitimate\\", title=\\"Proporsi legitimate per tipe URL\\")\\n",\n    "for i, v in enumerate(tt[\\"proporsi legit\\"][::-1]):\\n",\n    "    ax[1].text(v + 0.01, i, f\\"{v:.1%}\\", va=\\"center\\")\\n",\n    "save_fig(FIG_DIR, \\"01_url_types\\")\\n",\n    "rule_auc = roc_auc_score(y, (TYPE_TR == \\"beranda https://www\\").astype(int))\\n",\n    "print(f\\"AUC aturan \'beranda https://www = legitimate\': {rule_auc:.4f}\\")\\n",\n    "tt.style.format({\\"porsi train\\": \\"{:.1%}\\", \\"porsi test\\": \\"{:.1%}\\", \\"proporsi legit\\": \\"{:.1%}\\", \\"jumlah\\": \\"{:,.0f}\\"})"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "c2d0c0ed",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Dua tipe URL menjelaskan 85% data dan hampir seluruh label: host IP 96,7% phishing, beranda `https://www` 96,6% legitimate. Sisanya (15%) sebagian besar phishing (4,8% legitimate). Porsi tiap tipe di test sama persis dengan train. Aturan \\"beranda = legitimate\\" saja memberi AUC 0,959, sehingga sebagian besar pekerjaan model sebenarnya adalah mengenali struktur ini."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "09c9bfab",\n   "metadata": {},\n   "source": [\n    "### 3.2 Fitur bawaan per kelas"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "b1e9f85f",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "show = [\\"url_length\\", \\"url_entropy\\", \\"path_length\\", \\"percentage_numeric_chars\\", \\"token_count\\", \\"domain_name_length\\"]\\n",\n    "fig, axes = plt.subplots(2, 3, figsize=(16, 7.5))\\n",\n    "for a, c in zip(axes.flat, show):\\n",\n    "    lo, hi = train[c].quantile([0.005, 0.995])\\n",\n    "    for k, col, lab in [(1, C1, \\"legitimate\\"), (0, C2, \\"phishing\\")]:\\n",\n    "        a.hist(train.loc[train[TARGET] == k, c].clip(lo, hi), bins=50, alpha=0.55, density=True, color=col, label=lab)\\n",\n    "    a.set(title=c, ylabel=\\"densitas\\")\\n",\n    "axes[0, 0].legend()\\n",\n    "save_fig(FIG_DIR, \\"02_provided_features\\")\\n",\n    "single = pd.Series({c: max(roc_auc_score(y, train[c]), 1 - roc_auc_score(y, train[c])) for c in PROVIDED}).sort_values(ascending=False)\\n",\n    "single.head(8).to_frame(\\"AUC satu fitur\\").style.format(\\"{:.3f}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "2ef99a84",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Fitur bawaan yang paling memisahkan kelas sendirian adalah panjang path (AUC 0,957), jumlah digit (0,944), persen digit (0,943), dan flag HTTPS (0,939). Semuanya adalah cara lain untuk mengatakan \\"beranda https polos atau bukan\\": beranda tidak punya path, tidak punya digit, dan memakai HTTPS."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "5f2b8eb7",\n   "metadata": {},\n   "source": [\n    "### 3.3 Apakah fitur bawaan sesuai dengan URL-nya?\\n",\n    "\\n",\n    "Sebagian besar fitur bisa dihitung ulang langsung dari string URL. Jika fitur bawaan tidak sama dengan hasil hitung ulang,\\n",\n    "berarti nilainya diubah oleh penyusun data."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "43743faf",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "CLEAN_TR, CLEAN_TE = recompute(train.URL), recompute(test.URL)\\n",\n    "MIS_TR, MIS_TE = mismatch(train, CLEAN_TR), mismatch(test, CLEAN_TE)\\n",\n    "print(\\"Cocok persis dengan hasil hitung ulang: url_length\\", np.mean(train.url_length == CLEAN_TR.u_len).round(3),\\n",\n    "      \\"| number_of_digits\\", np.mean(train.number_of_digits == CLEAN_TR.u_digits).round(3),\\n",\n    "      \\"| dot_count\\", np.mean(train.dot_count == train.URL.str.count(r\\"\\\\.\\")).round(3))\\n",\n    "rate = MIS_TR.groupby([TYPE_TR, train[TARGET].map({1: \\"legit\\", 0: \\"phishing\\"})]).mean().T\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(16, 4.6), gridspec_kw={\\"width_ratios\\": [1.4, 1]})\\n",\n    "sns.heatmap(rate[[c for c in rate.columns if c[0] in ORDER]], annot=True, fmt=\\".0%\\", cmap=\\"Blues\\", cbar=False, ax=ax[0])\\n",\n    "ax[0].set(xlabel=\\"tipe URL, label\\", ylabel=\\"\\", title=\\"Porsi nilai yang berbeda dari hasil hitung ulang\\")\\n",\n    "m = MIS_TR.beda_entropy == 1\\n",\n    "ax[1].scatter(CLEAN_TR.u_entropy[~m], train.url_entropy[~m], s=2, alpha=0.2, color=C1, label=\\"sama\\")\\n",\n    "ax[1].scatter(CLEAN_TR.u_entropy[m], train.url_entropy[m], s=2, alpha=0.2, color=C2, label=\\"berbeda\\")\\n",\n    "ax[1].set(xlabel=\\"entropi dihitung dari URL\\", ylabel=\\"url_entropy bawaan\\", title=\\"Entropi: bawaan vs dihitung ulang\\"); ax[1].legend(markerscale=6)\\n",\n    "save_fig(FIG_DIR, \\"03_feature_noise\\")\\n",\n    "print(\\"Porsi baris dengan minimal satu nilai berbeda: train\\", (MIS_TR.sum(1) > 0).mean().round(3), \\"| test\\", (MIS_TE.sum(1) > 0).mean().round(3))"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "ecf45bd7",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Panjang URL, jumlah digit, dan jumlah titik cocok 100% dengan string URL. Namun entropi, panjang path, persen digit, dan jumlah token berbeda di 14–29% baris, dan 56% baris punya minimal satu nilai yang berbeda, di train maupun test. Heatmap menunjukkan porsinya hampir sama untuk label legitimate dan phishing di dalam tipe URL yang sama, jadi nilai-nilai ini tidak diubah berdasarkan label secara langsung. Grafik kanan memperlihatkan bentuk perubahannya: entropi yang diubah tersebar acak di sekitar nilai aslinya. Ini tanda bahwa penyusun data menyisipkan noise ke sebagian fitur."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "64cd9d4a",\n   "metadata": {},\n   "source": [\n    "### 3.4 Label yang berlawanan dengan tipe URL-nya"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "b32bb73a",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "odd_ip = (TYPE_TR == \\"host IP\\") & (train[TARGET] == 1)\\n",\n    "odd_home = (TYPE_TR == \\"beranda https://www\\") & (train[TARGET] == 0)\\n",\n    "print(f\\"Host IP berlabel legitimate: {odd_ip.sum():,} ({odd_ip.sum() / (TYPE_TR == \'host IP\').sum():.1%} dari host IP)\\")\\n",\n    "print(f\\"Beranda https://www berlabel phishing: {odd_home.sum():,} ({odd_home.sum() / (TYPE_TR == \'beranda https://www\').sum():.1%} dari beranda)\\")\\n",\n    "dups = train[train.URL.duplicated(keep=False)].groupby(\\"URL\\")[TARGET].nunique()\\n",\n    "print(f\\"URL duplikat dengan label berbeda: {(dups > 1).sum()} dari {len(dups)}\\")\\n",\n    "# Di dalam host IP: seberapa bisa label dibedakan oleh entropi bawaan vs entropi yang dihitung ulang?\\n",\n    "ipm = (TYPE_TR == \\"host IP\\").values\\n",\n    "cv = StratifiedKFold(5, shuffle=True, random_state=0)\\n",\n    "ent_auc = {}\\n",\n    "for name, col in [(\\"url_entropy bawaan\\", train.url_entropy), (\\"entropi dihitung dari URL\\", CLEAN_TR.u_entropy)]:\\n",\n    "    p = cross_val_predict(lgb_model(0, n_estimators=200), col[ipm].to_frame(), y[ipm], cv=cv, method=\\"predict_proba\\")[:, 1]\\n",\n    "    ent_auc[name] = roc_auc_score(y[ipm], p)\\n",\n    "print(\\"AUC di dalam host IP, satu fitur:\\", {k: round(v, 3) for k, v in ent_auc.items()})\\n",\n    "pd.DataFrame({\\"host IP berlabel legitimate\\": train.URL[odd_ip].sample(6, random_state=0).values,\\n",\n    "              \\"beranda berlabel phishing\\": train.URL[odd_home].sample(6, random_state=0).values})"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "ae11b6c4",\n   "metadata": {},\n   "source": [\n    "**Temuan.** 1.299 URL host IP (3,3%) berlabel legitimate, padahal bentuknya sama dengan malware lain, misalnya `http://59.89.186.229:59571/bin.sh`. Sebaliknya, 1.017 beranda biasa (3,4%) berlabel phishing. Ada juga 13 URL duplikat dengan label berbeda. Label-label ini kemungkinan besar keliru. Hal yang menarik: di dalam host IP, entropi **bawaan** memisahkan label dengan AUC 0,90, lebih tinggi dari entropi yang dihitung dari URL (0,83). Artinya noise yang disisipkan ikut membawa jejak label, dan model bisa memanfaatkannya tanpa memahami URL-nya."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "f46358e5",\n   "metadata": {},\n   "source": [\n    "### 3.5 Apakah test berasal dari distribusi yang sama?"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "fef6805a",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "adv_X = pd.concat([train[PROVIDED], test[PROVIDED]], ignore_index=True)\\n",\n    "adv_y = np.r_[np.zeros(len(train)), np.ones(len(test))]\\n",\n    "adv_p = cross_val_predict(lgb_model(0, n_estimators=200), adv_X, adv_y, cv=cv, method=\\"predict_proba\\")[:, 1]\\n",\n    "print(f\\"Adversarial validation AUC train vs test: {roc_auc_score(adv_y, adv_p):.3f}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "688103b5",\n   "metadata": {},\n   "source": [\n    "**Temuan.** AUC 0,498, praktis acak. Train dan test disusun dengan cara yang sama, termasuk noise pada fitur, sehingga skor cross-validation layak dipercaya untuk test."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "592dfefb",\n   "metadata": {},\n   "source": [\n    "## 4. Preprocessing\\n",\n    "\\n",\n    "Keputusan yang diambil dari EDA:\\n",\n    "\\n",\n    "- **Fitur bawaan dipakai apa adanya**, karena kompetisi menilai prediksi pada data yang disusun dengan cara yang sama.\\n",\n    "- **Fitur bersih dihitung ulang dari URL** (20 fitur: panjang host, kedalaman path, port, jumlah huruf besar, ekstensi\\n",\n    "  berisiko, entropi asli, dan lain-lain). Model yang hanya memakai fitur bersih menunjukkan seberapa jauh kita bisa tanpa\\n",\n    "  bergantung pada nilai yang diubah penyusun data.\\n",\n    "- **Penanda perbedaan** (4 kolom) disiapkan untuk diuji, bukan langsung dipakai.\\n",\n    "- **String URL** dipakai langsung oleh model teks TF-IDF karakter 2–5."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "9f320f1f",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "X_prov, X_clean = train[PROVIDED], CLEAN_TR\\n",\n    "X_both = pd.concat([train[PROVIDED], CLEAN_TR], axis=1)\\n",\n    "X_all = pd.concat([X_both, MIS_TR], axis=1)\\n",\n    "print({k: v.shape[1] for k, v in {\\"bawaan\\": X_prov, \\"bersih\\": X_clean, \\"bawaan + bersih\\": X_both, \\"+ penanda\\": X_all}.items()})\\n",\n    "RESULTS, OOF = {}, {}\\n",\n    "\\n",\n    "def record(name, oof):\\n",\n    "    s = auc_by_seed(oof, y)\\n",\n    "    OOF[name] = np.atleast_2d(oof).mean(0)\\n",\n    "    RESULTS[name] = {\\"AUC OOF\\": np.mean(s), \\"std antar seed\\": np.std(s)}\\n",\n    "    return f\\"{name}: AUC {np.mean(s):.5f} ± {np.std(s):.5f}\\""\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "b310cefb",\n   "metadata": {},\n   "source": [\n    "## 5. Baseline\\n",\n    "\\n",\n    "Semua skor adalah AUC out-of-fold dari Stratified 5-Fold yang diulang dengan 3 seed. Baseline: aturan satu baris dari\\n",\n    "bagian 3.1, dan regresi logistik pada 16 fitur bawaan."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "9015564f",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "print(record(\\"aturan beranda https://www\\", np.tile((TYPE_TR == \\"beranda https://www\\").astype(float).values, (len(SEEDS), 1))))\\n",\n    "print(record(\\"regresi logistik, fitur bawaan\\", cv_predict(logreg_model, X_prov, y, SEEDS)))"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "6261f197",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Aturan beranda memberi AUC 0,9591, dan regresi logistik pada 16 fitur bawaan menaikkannya ke 0,9712. Batas antara kedua kelas tidak linear: kombinasi seperti \\"host IP tanpa path\\" atau \\"beranda dengan digit\\" butuh model berbasis pohon."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "7c8137cd",\n   "metadata": {},\n   "source": [\n    "## 6. Model\\n",\n    "\\n",\n    "LightGBM pada empat set fitur, model teks TF-IDF pada string URL, dan rata-rata peringkat keduanya."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "5544f454",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "t = time.time()\\n",\n    "for name, X in [(\\"LightGBM, fitur bersih dari URL\\", X_clean), (\\"LightGBM, fitur bawaan\\", X_prov),\\n",\n    "                (\\"LightGBM, bawaan + bersih\\", X_both), (\\"LightGBM, bawaan + bersih + penanda\\", X_all)]:\\n",\n    "    print(record(name, cv_predict(lgb_model, X, y, SEEDS)), f\\"({(time.time() - t) / 60:.1f} menit)\\")\\n",\n    "print(record(\\"TF-IDF karakter + regresi logistik\\", cv_predict(tfidf_model, train.URL, y, SEEDS)), f\\"({(time.time() - t) / 60:.1f} menit)\\")\\n",\n    "OOF[\\"rata-rata peringkat: LightGBM bawaan + bersih & TF-IDF\\"] = rank_mean(OOF[\\"LightGBM, bawaan + bersih\\"], OOF[\\"TF-IDF karakter + regresi logistik\\"])\\n",\n    "RESULTS[\\"rata-rata peringkat: LightGBM bawaan + bersih & TF-IDF\\"] = {\\"AUC OOF\\": roc_auc_score(y, OOF[\\"rata-rata peringkat: LightGBM bawaan + bersih & TF-IDF\\"]), \\"std antar seed\\": np.nan}"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "49776fdd",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "res = pd.DataFrame(RESULTS).T.sort_values(\\"AUC OOF\\")\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(16, 4.8), gridspec_kw={\\"width_ratios\\": [1.3, 1]})\\n",\n    "cols = [C2 if \\"bawaan\\" in n and \\"LightGBM\\" in n else (C3 if \\"bersih dari URL\\" in n or \\"TF-IDF\\" in n else C1) for n in res.index]\\n",\n    "ax[0].barh(res.index, res[\\"AUC OOF\\"], xerr=res[\\"std antar seed\\"].fillna(0), color=cols)\\n",\n    "ax[0].set_xlim(res[\\"AUC OOF\\"].min() - 0.005, 1.0005); ax[0].set(xlabel=\\"AUC OOF\\", title=\\"Perbandingan model\\")\\n",\n    "for n in [\\"LightGBM, fitur bersih dari URL\\", \\"LightGBM, fitur bawaan\\", \\"LightGBM, bawaan + bersih\\", \\"TF-IDF karakter + regresi logistik\\"]:\\n",\n    "    fpr, tpr, _ = roc_curve(y, OOF[n])\\n",\n    "    ax[1].plot(fpr, tpr, label=f\\"{n} ({RESULTS[n][\'AUC OOF\']:.4f})\\")\\n",\n    "ax[1].set(xscale=\\"log\\", xlim=(1e-3, 1), xlabel=\\"false positive rate (log)\\", ylabel=\\"true positive rate\\", title=\\"Kurva ROC (OOF)\\")\\n",\n    "ax[1].legend(fontsize=8, loc=\\"lower right\\")\\n",\n    "save_fig(FIG_DIR, \\"04_model_comparison\\")\\n",\n    "res.style.format({\\"AUC OOF\\": \\"{:.5f}\\", \\"std antar seed\\": \\"{:.5f}\\"})"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "217177fa",\n   "metadata": {},\n   "source": [\n    "**Temuan.** LightGBM pada fitur bawaan mencapai 0,99309. Menambahkan fitur yang dihitung ulang dari URL menaikkannya sedikit ke 0,99326, dan penanda perbedaan tidak menambah apa pun (0,99327). Model yang **hanya** memakai fitur bersih dari URL mencapai 0,98755, lebih rendah 0,006 dari model dengan fitur bawaan; selisih ini adalah nilai informasi yang dibawa fitur yang sudah diubah. Model teks TF-IDF karakter (0,975) kalah dari model fitur, dan rata-rata peringkatnya dengan LightGBM malah menurunkan skor (0,988). Variasi antar seed sangat kecil (±0,00005) untuk semua model LightGBM."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "48594c4c",\n   "metadata": {},\n   "source": [\n    "### 6.1 Model akhir\\n",\n    "\\n",\n    "Model dipilih dengan aturan parsimoni: model paling sederhana yang AUC-nya tidak lebih buruk dari model terbaik lebih dari\\n",\n    "dua standar deviasi antar seed. Urutan kesederhanaan: LightGBM fitur bawaan, bawaan + bersih, + penanda, lalu\\n",\n    "rata-rata peringkat dengan TF-IDF."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "3c2f3019",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "best = res[\\"AUC OOF\\"].idxmax()\\n",\n    "tol = 2 * np.nanmax([res.loc[best, \\"std antar seed\\"], 1e-5])\\n",\n    "candidates = [\\"LightGBM, fitur bawaan\\", \\"LightGBM, bawaan + bersih\\", \\"LightGBM, bawaan + bersih + penanda\\",\\n",\n    "              \\"rata-rata peringkat: LightGBM bawaan + bersih & TF-IDF\\"]\\n",\n    "FINAL_NAME = next(n for n in candidates if res.loc[n, \\"AUC OOF\\"] >= res.loc[best, \\"AUC OOF\\"] - tol)\\n",\n    "print(f\\"Terbaik: {best} ({res.loc[best, \'AUC OOF\']:.5f}) | Model akhir: {FINAL_NAME} ({res.loc[FINAL_NAME, \'AUC OOF\']:.5f})\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "d09dc697",\n   "metadata": {},\n   "source": [\n    "## 7. Interpretasi dan analisis error\\n",\n    "\\n",\n    "### 7.1 Fitur apa yang dipakai model?"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "6b730114",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "imp_model = lgb_model(0).fit(X_both, y)\\n",\n    "imp = pd.Series(imp_model.booster_.feature_importance(\\"gain\\"), index=X_both.columns)\\n",\n    "imp = (imp / imp.sum()).sort_values().tail(15)\\n",\n    "fig, ax = plt.subplots(figsize=(10, 5.5))\\n",\n    "ax.barh(imp.index, imp.values, color=[C2 if c in PROVIDED else C3 for c in imp.index])\\n",\n    "pct_axis(ax, 0, axis=\\"x\\"); ax.set(xlabel=\\"porsi total gain\\", title=\\"15 fitur terpenting (oranye = bawaan, hijau = dihitung dari URL)\\")\\n",\n    "save_fig(FIG_DIR, \\"05_importance\\")\\n",\n    "print(f\\"Porsi gain fitur bawaan: {imp_model.booster_.feature_importance(\'gain\')[:len(PROVIDED)].sum() / imp_model.booster_.feature_importance(\'gain\').sum():.0%}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "716483a0",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Panjang path mendominasi: versi bawaan menyumbang 68% gain dan versi yang dihitung ulang 16%. Keduanya dipakai bersama karena versi bawaan berisi noise di 14% baris, dan model memakai versi bersih untuk mengoreksinya. Berikutnya entropi bawaan (7%), penanda `www` (3%), dan entropi asli. Fitur bawaan secara total menyumbang 78% gain. Jadi pertanyaan utama model adalah \\"apakah URL ini punya path?\\", yang sama dengan membedakan beranda dari URL lain."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "701fa452",\n   "metadata": {},\n   "source": [\n    "### 7.2 Di mana model salah?"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "d34f39f7",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "p_fin = OOF[FINAL_NAME]\\n",\n    "err = pd.DataFrame({\\"URL\\": train.URL, \\"tipe\\": TYPE_TR, \\"label\\": y, \\"skor\\": p_fin})\\n",\n    "err[\\"salah\\"] = (err.skor > 0.5).astype(int) != err.label\\n",\n    "by = err.groupby([\\"tipe\\", \\"label\\"]).agg(baris=(\\"skor\\", \\"size\\"), salah=(\\"salah\\", \\"mean\\"), skor_median=(\\"skor\\", \\"median\\"))\\n",\n    "by[\\"porsi seluruh kesalahan\\"] = err.groupby([\\"tipe\\", \\"label\\"]).salah.sum() / err.salah.sum()\\n",\n    "fig, axes = plt.subplots(1, 3, figsize=(17, 4.2), sharey=True)\\n",\n    "for a, tp in zip(axes, ORDER):\\n",\n    "    for k, col, lab in [(1, C1, \\"legitimate\\"), (0, C2, \\"phishing\\")]:\\n",\n    "        s = err.skor[(err.tipe == tp) & (err.label == k)]\\n",\n    "        a.hist(s, bins=np.linspace(0, 1, 41), color=col, alpha=0.6, label=f\\"{lab} (n={len(s):,})\\", log=True)\\n",\n    "    a.set(title=tp, xlabel=\\"skor model (peluang legitimate)\\"); a.legend(fontsize=8)\\n",\n    "axes[0].set_ylabel(\\"jumlah URL (log)\\")\\n",\n    "save_fig(FIG_DIR, \\"06_errors\\")\\n",\n    "display(by.style.format({\\"baris\\": \\"{:,.0f}\\", \\"salah\\": \\"{:.1%}\\", \\"skor_median\\": \\"{:.3f}\\", \\"porsi seluruh kesalahan\\": \\"{:.0%}\\"}))\\n",\n    "worst = err.assign(loss=np.abs(err.label - err.skor)).sort_values(\\"loss\\", ascending=False)\\n",\n    "worst.head(15)[[\\"URL\\", \\"tipe\\", \\"label\\", \\"skor\\"]]"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "5876c932",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Pada ambang 0,5, **semua** host IP berlabel legitimate dan semua beranda berlabel phishing diprediksi salah, dan dua kelompok ini memuat 92% seluruh kesalahan. Model memberi skor yang sesuai dengan bentuk URL-nya (median 0,145 untuk host IP berlabel legitimate, 0,859 untuk beranda berlabel phishing), dan menurut kami di sinilah model benar dan labelnya yang keliru. Kelompok ketiga adalah URL legitimate yang bukan beranda (579 URL, 28,8% salah), misalnya `support.google.com/chrome/answer/...` atau `web.archive.org`. Ini kelemahan nyata: karena hampir semua URL legitimate di data latih adalah beranda, model belajar bahwa URL dengan path itu mencurigakan. Di dunia nyata, model ini akan menandai banyak tautan sah ke halaman dalam situs."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "4457098a",\n   "metadata": {},\n   "source": [\n    "## 8. Submission\\n",\n    "\\n",\n    "Model akhir dilatih ulang pada seluruh data latih. Untuk LightGBM, prediksi dirata-rata dari 3 seed."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "55ffef11",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "X_te = {\\"LightGBM, fitur bawaan\\": test[PROVIDED], \\"LightGBM, bawaan + bersih\\": pd.concat([test[PROVIDED], CLEAN_TE], axis=1),\\n",\n    "        \\"LightGBM, bawaan + bersih + penanda\\": pd.concat([test[PROVIDED], CLEAN_TE, MIS_TE], axis=1)}\\n",\n    "X_trn = {\\"LightGBM, fitur bawaan\\": X_prov, \\"LightGBM, bawaan + bersih\\": X_both, \\"LightGBM, bawaan + bersih + penanda\\": X_all}\\n",\n    "key = FINAL_NAME if FINAL_NAME in X_te else \\"LightGBM, bawaan + bersih\\"\\n",\n    "p_lgb = np.mean([lgb_model(s).fit(X_trn[key], y).predict_proba(X_te[key])[:, 1] for s in SEEDS], axis=0)\\n",\n    "if FINAL_NAME.startswith(\\"rata-rata\\"):\\n",\n    "    p_txt = tfidf_model(0).fit(train.URL, y).predict_proba(test.URL)[:, 1]\\n",\n    "    p_test = rank_mean(p_lgb, p_txt)\\n",\n    "else:\\n",\n    "    p_test = p_lgb\\n",\n    "target_col = sample.columns[1]\\n",\n    "sub = sample[[ID]].merge(pd.DataFrame({ID: test[ID], target_col: p_test}), on=ID, how=\\"left\\")\\n",\n    "assert sub[target_col].notna().all() and len(sub) == len(sample)\\n",\n    "sub.to_csv(OUT_DIR / \\"submission.csv\\", index=False)\\n",\n    "res.to_csv(OUT_DIR / \\"cv_results.csv\\"); by.to_csv(OUT_DIR / \\"errors_by_type.csv\\")\\n",\n    "print(f\\"Model: {FINAL_NAME} | proporsi skor > 0,5 di test: {(p_test > 0.5).mean():.1%} (train legit {y.mean():.1%})\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "93dc085e",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Proporsi skor di atas 0,5 di test (37,1%) sama dengan proporsi legitimate di train (37,6%)."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "2482e8bf",\n   "metadata": {},\n   "source": [\n    "## 9. Kesimpulan\\n",\n    "\\n",\n    "1. **AUC 0,99 sebagian besar berasal dari struktur dataset.** Beranda `https://www` hampir selalu legitimate dan host IP hampir selalu phishing; aturan satu baris sudah memberi AUC 0,959.\\n",\n    "2. **Sisa error didominasi label yang tampak keliru.** 92% kesalahan ada di dua kelompok yang labelnya berlawanan dengan isi URL. Model yang lebih kuat tidak akan banyak membantu di sini.\\n",\n    "3. **Fitur yang diubah ikut membawa informasi.** Fitur bawaan yang disisipi noise memberi AUC lebih tinggi daripada fitur bersih dari URL (0,9931 vs 0,9876). Untuk kompetisi, keduanya dipakai; untuk sistem sungguhan, model fitur bersih (0,9876) adalah gambaran yang lebih jujur.\\n",\n    "4. **Hasil.** Late submission private 0,99390, di atas submission tim saat kompetisi (0,99378) dan 0,0002 di bawah peringkat 1.\\n",\n    "\\n",\n    "**Keterbatasan.** Kelas legitimate hampir seluruhnya beranda, sehingga model tidak belajar membedakan halaman dalam situs yang sah dari halaman phishing. Evaluasi pada URL dunia nyata yang lebih beragam akan menghasilkan skor yang jauh lebih rendah.\\n",\n    "\\n",\n    "### Jejak lingkungan"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "0d3ef189",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "import platform\\n",\n    "pkgs = [\\"numpy\\", \\"pandas\\", \\"scikit-learn\\", \\"lightgbm\\", \\"matplotlib\\", \\"seaborn\\"]\\n",\n    "print(\\" | \\".join([f\\"python {platform.python_version()}\\"] + [f\\"{p} {version(p)}\\" for p in pkgs]))\\n",\n    "print(f\\"Waktu eksekusi total: {(time.time() - T0) / 60:.1f} menit\\")"\n   ]\n  }\n ],\n "metadata": {\n  "kernelspec": {\n   "display_name": "Python 3",\n   "language": "python",\n   "name": "python3"\n  },\n  "language_info": {\n   "name": "python",\n   "version": "3.11"\n  }\n },\n "nbformat": 4,\n "nbformat_minor": 5\n}')

